Section CsOk.
Variable SEGS : list Segment.
Variable A : atable.
Variable nx0 : nat.
Variable LIMIT : Z.
Variable SINV : env -> (word -> option byte) -> Prop.
Variable argH : env -> word -> bool.
Variable FS0 : Fs.Fs.
#[local] Notation cs_ok := (APS.cs_ok SEGS A LIMIT SINV argH FS0).
Scheme kc__9 := Elimination for OSSVerify.Proofs.boost_beast.http_request.lib.As.AsanPlanSound.APS.cs_ok Sort Prop.

(* [comment removed for export] *)
Lemma cs_ok_refuse : forall E cs R FULL model,
  cs_ok E cs R FULL model ->
